SELECT COUNT(*) AS products_still_listed
FROM products
WHERE delist_after IS NULL;

SELECT COUNT(*) AS products_still_listed
FROM products
WHERE delist_after IS NULL;

SELECT product_name, delist_after AS last_month_on_sale
FROM products
WHERE delist_after IS NOT NULL;

SELECT product_name, delist_after AS last_month_on_sale
FROM products
WHERE delist_after IS NOT NULL;

SELECT COUNT(*) AS planned_promotions, AVG(discount_pct) AS avg_discount_pct
FROM promotions
WHERE month LIKE '2025-%';
